head.script:
//
// Warm the feed cache in parallel with Blogger's widgets.js so image
// injection doesn't wait on it. Consumed by fxFeedImages() below.
(function(){
  var feedCache=location.origin+'/feeds/posts/default?alt=json&max-results=24&fields=entry(title,link,content)';
  window.__feedP=null;
  if(!window.fetch)return;
  try{window.__feedP=fetch(feedCache).then(function(r){return r.json();}).catch(function(){return null;});}catch(e){}
})();
// Live widgets must NOT start until the LCP hero image has loaded, else they
// compete with it for 4G bandwidth and push LCP out. `__fxLive` resolves when
// the hero <img> fires onload (see fxInjectImages); a hard failsafe in the
// widget scripts guarantees they always run.
(function(){
  if(window.__fxLive)return;
  var resolveFn=null;
  window.__fxLive=new Promise(function(res){resolveFn=res;});
  window.__fxLiveStart=function(){if(resolveFn){var r=resolveFn;resolveFn=null;try{r();}catch(e){}}};
})();
function __fxLiveGo(){
  if(!(window.__fxLiveStart))return;
  try{window.__fxLiveStart();}catch(e){}
}
//

  //
  var FX_DEFAULTS={
    colors:{bg:'#131722',panel:'#1e222d',panel2:'#262b38',border:'#2a2e39',ink:'#d1d4dc',muted:'#9aa0ae',head:'#ffffff',brand:'#0a8f68',brand2:'#00c690',up:'#089981',down:'#f6465d',navbg:'#0e1119',headbg:'#0e1119'},
    colorsLight:{bg:'#f4f6fb',panel:'#ffffff',panel2:'#eef1f7',border:'#e3e8f0',ink:'#1e2430',muted:'#5c6470',head:'#0f1626',brand:'#0a8f68',brand2:'#009e76',up:'#089981',down:'#e0314a',navbg:'#ffffff',headbg:'#ffffff'},
    logo:'', siteName:'', tagline:'',
nav:[
      {label:'طھظˆطµظٹط§طھ ظپظˆط±ظƒط³',url:'/search/label/طھظˆطµظٹط§طھ%20ظپظˆط±ظƒط³'},
      {label:'ظˆط³ط·ط§ط، ظ…ظˆط«ظˆظ‚ظˆظ†',url:'/search/label/ظˆط³ط·ط§ط،%20ظ…ظˆط«ظˆظ‚ظˆظ†'},
      {label:'ط£ط³ط¹ط§ط± ط§ظ„ط¹ظ…ظ„ط§طھ',url:'/search/label/ط£ط³ط¹ط§ط±%20ط§ظ„ط¹ظ…ظ„ط§طھ'},
      {label:'ط§ظ„ط°ظ‡ط¨ ظˆط§ظ„ظ†ظپط·',url:'/search/label/ط§ظ„ط°ظ‡ط¨%20ظˆط§ظ„ظ†ظپط·'},
      {label:'طھط­ظ„ظٹظ„ ظپظ†ظٹ',url:'/search/label/طھط­ظ„ظٹظ„%20ظپظ†ظٹ'},
      {label:'ط§ظ„ط¹ظ…ظ„ط§طھ ط§ظ„ط±ظ‚ظ…ظٹط©',url:'/search/label/ط§ظ„ط¹ظ…ظ„ط§طھ%20ط§ظ„ط±ظ‚ظ…ظٹط©'},
      {label:'ط£ط®ط¨ط§ط± ط§ظ„ط£ط³ظˆط§ظ‚',url:'/search/label/ط£ط®ط¨ط§ط±%20ط§ظ„ط£ط³ظˆط§ظ‚'}
    ],
    footerAbout:'',
    footerLinks:[
      {label:'ط§ظ„طµظپط­ط© ط§ظ„ط±ط¦ظٹط³ظٹط©',url:'data:blog.homepageUrl'},
      {label:'ط®ط±ظٹط·ط© ط§ظ„ظ…ظˆظ‚ط¹',url:'/sitemap.xml'},
      {label:'طھط؛ط°ظٹط© RSS',url:'/feeds/posts/default'},
      {label:'ط§ظ„ظˆط³ط·ط§ط، ط§ظ„ظ…ظˆط«ظˆظ‚ظˆظ†',url:'/search/label/ظˆط³ط·ط§ط،%20ظ…ظˆط«ظˆظ‚ظˆظ†'},
      {label:'طھظˆطµظٹط§طھ ط§ظ„ظپظˆط±ظƒط³',url:'/search/label/طھظˆطµظٹط§طھ%20ظپظˆط±ظƒط³'}
    ],
    adsenseClient:'', adUnitCode:'', ticker:true, darkMode:true
  };
  var FX={};
  function fxMerge(c){
    var m={};for(var k in FX_DEFAULTS){m[k]=FX_DEFAULTS[k];}
    c=c||{};
    for(var k2 in c){
      if((k2==='colors'||k2==='colorsLight')&&c[k2]){m[k2]={};for(var cc in FX_DEFAULTS[k2]){m[k2][cc]=FX_DEFAULTS[k2][cc];}for(var cc2 in c[k2]){m[k2][cc2]=c[k2][cc2];}}
      else if(k2==='nav'&&c[k2]&&c[k2].length){m.nav=c[k2];}
      else if(k2==='footerLinks'&&c[k2]&&c[k2].length){m.footerLinks=c[k2];}
      else{m[k2]=c[k2];}
    }
    return m;
  }
  function fxTheme(){return localStorage.getItem('fxTheme')||(FX.darkMode===false?'light':'dark');}
  function fxApplyTheme(){
    var mode=fxTheme();
    document.body.classList.toggle('fx-light',mode==='light');
    var pal=(mode==='light')?FX.colorsLight:FX.colors;
    var root=document.documentElement.style;
    for(var k in pal){if(pal[k])root.setProperty('--'+k,pal[k]);}
    var btn=document.getElementById('fx-theme-toggle');
    if(btn){btn.setAttribute('aria-label',mode==='light'?'ط§ظ„ظˆط¶ط¹ ط§ظ„ظ„ظٹظ„ظٹ':'ط§ظ„ظˆط¶ط¹ ط§ظ„ظ†ظ‡ط§ط±ظٹ');btn.title=mode==='light'?'ط§ظ„ظˆط¶ط¹ ط§ظ„ظ„ظٹظ„ظٹ':'ط§ظ„ظˆط¶ط¹ ط§ظ„ظ†ظ‡ط§ط±ظٹ';}
    try{if(window.TradingView){location.reload();}}catch(e){}
  }
  function fxApplyBrand(){
    var logo=document.getElementById('fx-logo');
    var manual=document.querySelector('.fx-logo-sect img');
    var src=manual?manual.getAttribute('src'):FX.logo;
    if(logo&&src){logo.innerHTML='<img alt="'+document.title+'" src="'+src+'"/>';}
    if(FX.siteName){var b=document.querySelector('.brand-text b');if(b)b.textContent=FX.siteName;}
    if(FX.tagline){var s=document.querySelector('.brand-text span');if(s)s.textContent=FX.tagline;}
  }
  function fxApplyNav(){
    var nav=document.getElementById('fx-nav');
    if(!nav)return;
    var cur=decodeURIComponent(location.pathname);
    var links=nav.querySelectorAll('a');
    for(var i=0;i<links.length;i++){
      var href=decodeURIComponent(links[i].getAttribute('href')||'');
      var isHome=(href===location.origin+'/'||href==='/');
      var act=isHome?(cur==='/'||cur===''):(cur.indexOf(href.replace(/^.*\/search\/label\//,''))!==-1);
      if(act)links[i].classList.add('is-active');
    }
  }
  function fxApplyFooter(){
    if(FX.footerAbout){var a=document.getElementById('fx-footer-about');if(a)a.textContent=FX.footerAbout;}
    var fl=document.getElementById('fx-footer-links');
    if(fl&&!fl.querySelector('a')){
      var html='';
      for(var i=0;i<FX.footerLinks.length;i++){
        var it=FX.footerLinks[i];
        var url=(it.url==='data:blog.homepageUrl')?'/':it.url;
        html+='<a href="'+url+'">'+it.label+'</a>';
      }
      fl.innerHTML=html;
    }
  }
  function fxAdsense(){
    if(document.querySelector('script[src*="adsbygoogle.js"]'))return;
    if(FX.adsenseClient){
      var s=document.createElement('script');
      s.async=true;s.src='https://pagead2.googlesyndication.com/pagead/js/adsbygoogle.js?client='+FX.adsenseClient;
      s.crossOrigin='anonymous';
      document.head.appendChild(s);
    }
  }
  function fxInlineAd(){
    if(!FX.adUnitCode)return;
    var div=document.createElement('div');
    div.className='fx-in-ad';
    div.innerHTML=FX.adUnitCode;
    var content=document.querySelector('.post-content');
    if(content){var p=content.querySelector('p');if(p)p.after(div);else content.appendChild(div);}
    else{document.body.appendChild(div);}
    try{window.adsbygoogle=window.adsbygoogle||[];window.adsbygoogle.push({});}catch(e){}
  }
  function fxHideEmpty(){
    var zones=document.querySelectorAll('.fx-ad');
    for(var i=0;i<zones.length;i++){if(!zones[i].querySelector('.widget'))zones[i].style.display='none';}
    if(FX.ticker===false){var tk=document.querySelector('.ticker');if(tk)tk.style.display='none';}
  }
  function fxOgImage(){
    var imgs=document.querySelectorAll('.post-content img');
    if(!imgs.length)return;
    var src=imgs[0].src;
    if(!src)return;
    ['og:image','twitter:image'].forEach(function(prop){
      var m=document.querySelector('meta[property="'+prop+'"],meta[name="'+prop+'"]');
      if(m)m.setAttribute('content',src);
    });
    var ld=document.getElementById('fx-jsonld');
    if(ld){
      try{
        var j=JSON.parse(ld.textContent);
        j.image=src;j.thumbnailUrl=src;
        ld.textContent=JSON.stringify(j);
      }catch(e){}
    }
  }
  function fxPlaceholders(){
    document.querySelectorAll('.hero-thumb, .card-thumb').forEach(function(a){
      if(!a.querySelector('img')){
        var t=a.getAttribute('data-title')||'ظپ';
        var ph=document.createElement('div');
        ph.className='thumb-ph';ph.textContent=t.charAt(0);
        a.appendChild(ph);
      }
    });
  }
  function fxFeedImages(){
    var thumbs=[].slice.call(document.querySelectorAll('.hero-thumb, .card-thumb'));
    var missing=thumbs.filter(function(a){return !a.querySelector('img');});
    if(!missing.length)return;
    var need={};
    missing.forEach(function(a){
      var u=(a.getAttribute('href')||'').split('?')[0];
      if(u)need[u]=a;
    });
    var urls=Object.keys(need);
    if(!urls.length)return;
    var key='fxImgIndex';
    var ttl=4*60*1000;
    var useCache=false;
    try{
      var cached=JSON.parse(sessionStorage.getItem(key));
      if(cached&&cached.t&&cached.map&&(Date.now()-cached.t)<ttl){
        // Only trust the cache if it actually covers one of the needed URLs
        // (an empty/outdated map must never block fresh injection).
        useCache=urls.some(function(u){return !!cached.map[u];});
      }
    }catch(e){}
    if(useCache){fxInjectImages(need,cached.map);return;}
    var parseFeed=function(feed){
      var map={};
      (feed.feed.entry||[]).forEach(function(en){
        var alt=null;
        for(var i=0;i<(en.link||[]).length;i++){if(en.link[i].rel==='alternate'){alt=en.link[i];break;}}
        if(!alt)return;
        var u=(alt.href||'').split('?')[0];
        var m=(en.content&&en.content.$t||'').match(/<img[^>]+src=["']([^"']+)/i);
        if(u&&m)map[u]=m[1].replace(/&amp;/g,'&');
      });
      try{sessionStorage.setItem(key,JSON.stringify({t:Date.now(),map:map}));}catch(e){}
      fxInjectImages(need,map);
    };
    // Await the feed warmed in <head> (parallel to widgets.js) to avoid a
    // second request; fall back to a direct fetch only if the guide is absent.
    if(window.__feedP){window.__feedP.then(function(f){if(f)parseFeed(f);});return;}
    var max=Math.min(24,urls.length+8);
    fetch(location.origin+'/feeds/posts/default?alt=json&max-results='+max+'&fields=entry(title,link,content)')
      .then(function(r){return r.json();})
      .then(parseFeed)
      .catch(function(){});
  }
  function fxInjectImages(need,map){
    Object.keys(need).forEach(function(u){
      var img=map[u];
      if(!img)return;
      var a=need[u];
      var ph=a.querySelector('.thumb-ph');
      var isHero=a.className.indexOf('hero-thumb')!==-1;
      var w=isHero?680:560;
      var im=document.createElement('img');
      im.alt=a.getAttribute('data-title')||'';
      im.loading=isHero?'eager':'lazy';
      im.fetchPriority=isHero?'high':'auto';
      im.width=w;
      im.height=Math.round(w*9/16);
      // Resized + WebP via images.weserv.nl so the hero/cards load small and
      // fast (LCP). Fallback chain: optimizer â†’ original â†’ refetch feed once.
      im.onerror=function(){
        if(!im.dataset.fb){im.dataset.fb='1';im.src=img;return;}
        if(im.dataset.retry)return;
        im.dataset.retry='1';
        im.remove();
        try{sessionStorage.removeItem('fxImgIndex');}catch(e){}
        setTimeout(fxFeedImages,300);
      };
      // Hero (LCP): source is factory-capped at <=1440 so serve it DIRECT (the
      // source host is preconnected). weserv rescued only card thumbs, where a
      // slow/blocked fetch doesn't touch LCP.
      im.src=isHero?img:fxOpt(img,w);
      if(ph)ph.remove();
      a.insertBefore(im,a.firstChild);
      // Live widgets wait for the LCP hero image, so release them only once it
      // has actually painted (protects LCP from the ~160KB widget load).
      if(isHero){im.onload=function(){window.__fxLiveGo&&window.__fxLiveGo();};}
    });
  }
  function fxOpt(u,w){
    if(!u)return u;
    try{
      return 'https://images.weserv.nl/?url='+encodeURIComponent(u)+'&w='+w+'&output=webp&q=68';
    }catch(e){return u;}
  }
  function showDate(){
    var d=new Date();var days=['ط§ظ„ط£ط­ط¯','ط§ظ„ط§ط«ظ†ظٹظ†','ط§ظ„ط«ظ„ط§ط«ط§ط،','ط§ظ„ط£ط±ط¨ط¹ط§ط،','ط§ظ„ط®ظ…ظٹط³','ط§ظ„ط¬ظ…ط¹ط©','ط§ظ„ط³ط¨طھ'];
    var m=['ظٹظ†ط§ظٹط±','ظپط¨ط±ط§ظٹط±','ظ…ط§ط±ط³','ط£ط¨ط±ظٹظ„','ظ…ط§ظٹظˆ','ظٹظˆظ†ظٹظˆ','ظٹظˆظ„ظٹظˆ','ط£ط؛ط³ط·ط³','ط³ط¨طھظ…ط¨ط±','ط£ظƒطھظˆط¨ط±','ظ†ظˆظپظ…ط¨ط±','ط¯ظٹط³ظ…ط¨ط±'];
    var e=document.getElementById('fx-clock');
    if(e){e.textContent=days[d.getDay()]+' '+d.getDate()+' '+m[d.getMonth()]+' '+d.getFullYear()+' â€” '+d.toLocaleTimeString('en-GB');}
  }
  function fxMeta(){
    var set=function(sel,val){var m=document.querySelector(sel);if(m)m.setAttribute('content',val);};
    var og=document.querySelector('meta[property="og:description"]');
    var fill=function(){if(og&&og.getAttribute('content')){set('meta[name="description"]',og.getAttribute('content'));set('meta[name="twitter:description"]',og.getAttribute('content'));}};
    if(og&&og.getAttribute('content')){fill();}
    else{var bt=document.querySelector('h1');if(bt&&bt.textContent){og=document.createElement('meta');og.setAttribute('property','og:description');og.setAttribute('content','Forex Check â€” '+bt.textContent.replace(/\s+/g,' ').slice(0,150));document.head.appendChild(og);fill();}}
  }
  function initFx(){
    FX=fxMerge(window.FX_CONFIG);
    fxApplyTheme();fxApplyBrand();fxApplyNav();fxApplyFooter();fxAdsense();fxInlineAd();fxHideEmpty();fxPlaceholders();
    fxOgImage();
    fxMeta();
    fxFeedImages();
    showDate();setInterval(showDate,30000);
    var bt=document.getElementById('backtop');
    if(bt){window.addEventListener('scroll',function(){bt.classList.toggle('show',window.scrollY>500);});
      bt.addEventListener('click',function(){window.scrollTo({top:0,behavior:'smooth'});});}
    var tg=document.getElementById('fx-theme-toggle');
    if(tg){tg.addEventListener('click',function(){
        var next=(fxTheme()==='light')?'dark':'light';
        localStorage.setItem('fxTheme',next);
        fxApplyTheme();
      });}
  }
  window.addEventListener('DOMContentLoaded',initFx);
  //

div.script:
(function(){
  var cfg={"symbols":[{"proName":"FX_IDC:EURUSD","title":"EUR/USD"},{"proName":"FX_IDC:GBPUSD","title":"GBP/USD"},{"proName":"FX_IDC:USDJPY","title":"USD/JPY"},{"proName":"FX_IDC:XAUUSD","title":"Gold"},{"proName":"FX_IDC:USOIL","title":"WTI Oil"},{"proName":"BITSTAMP:BTCUSD","title":"BTC/USD"},{"proName":"NASDAQ:US100","title":"US 100"}],"showSymbolLogo":true,"colorTheme":"dark","isTransparent":true,"displayMode":"adaptive","locale":"ar"};
  function fxTV(){
    var box=document.querySelector('.ticker .tradingview-widget-container');
    if(!box)return;
    var s=document.createElement('script');
    s.type='text/javascript';s.async=true;
    s.src='https://s3.tradingview.com/external-embedding/embed-widget-ticker-tape.js';
    s.text=JSON.stringify(cfg);
    box.appendChild(s);
  }
  var _g=false,go=function(){if(_g)return;_g=true;fxTV();};
  // Wait for the LCP hero image, then load (so it never competes for
  // bandwidth during LCP); hard failsafe at 9.5s guarantees it still runs.
  var lst=window.__fxLive?window.__fxLive:null;
  if(lst){try{lst.then(function(){go();});}catch(e){go();}}else{go();}
  setTimeout(go,9500);
})();
